WITH filtered AS (SELECT id, customer_id, device, browser, started_at, country, UPPER(browser) AS browser_upper FROM sessions WHERE customer_id IS NOT NULL AND country IN ('DE', 'JP')) SELECT s.*, x.web_event_event_type, x.event_time FROM filtered s LEFT JOIN LATERAL (SELECT c.event_type AS web_event_event_type, c.event_time FROM web_events c WHERE c.session_id = s.id ORDER BY c.event_time DESC, c.id DESC LIMIT 1) x ON TRUE
